def is_prime_power(n):
    d = 2
    while d * d <= n:
        if n % d == 0:
            while n % d == 0:
                n //= d
            return n == 1
        d += 1
    return True

def next_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def previous_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    candidate = n - 1
    while not is_prime(candidate):
        candidate -= 1
    return candidate

import math


def sum_of_digit_factorials(n):
    n = abs(n)
    return sum(math.factorial(int(d)) for d in str(n))

def is_pandigital(n):
    s = str(n)
    if len(s) != 9:
        return False
    return set(s) == set('123456789')

def is_undulating_number(n):
    s = str(n)
    if len(s) < 3:
        return False
    if len(set(s)) != 2:
        return False
    for i in range(len(s) - 2):
        if s[i] != s[i + 2]:
            return False
    return True

