def sum_of_even_divisors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i % 2 == 0:
                total += i
            if j != i and j % 2 == 0:
                total += j
        i += 1
    return total

def sum_of_odd_divisors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i % 2 == 1:
                total += i
            if j != i and j % 2 == 1:
                total += j
        i += 1
    return total

def is_strictly_increasing_digits(n):
    s = str(abs(n))
    return all(s[i] < s[i + 1] for i in range(len(s) - 1))

def sum_proper_divisors(n):
    if n == 1:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            j = n // i
            total += i
            if j != i:
                total += j
        i += 1
    return total

def count_partitions(n, k):
    if k < 0 or n < 0:
        return 0
    if n == 0 and k == 0:
        return 1
    if k == 0 or k > n:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] = dp[i - 1][j - 1] + (dp[i - j][j] if i - j >= 0 else 0)
    return dp[n][k]

def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    x = n
    while x > 0:
        digits.append(x % b)
        x //= b
    return digits == digits[::-1]

def fibonacci_mod(n, m):
    def fib_pair(k):
        if k == 0:
            return (0 % m, 1 % m)
        a, b = fib_pair(k >> 1)
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return (d, (c + d) % m)
        else:
            return (c, d)
    return fib_pair(n)[0]

def count_digit_sum_in_range(low, high, s):
    def digit_sum(x):
        return sum(int(c) for c in str(x))
    count = 0
    for x in range(low, high + 1):
        if digit_sum(x) == s:
            count += 1
    return count

